<script setup>
import {dimensionFields,cardKindLabel} from '../knowledgeBaseAccess.js';
defineProps({card:{type:Object,required:true},showNote:Boolean});
</script>
<template><div class="card-content"><p class="card-meta">{{cardKindLabel(card)}} · v{{card.revision}}</p><p>{{card.knowledge_points?.map(p=>`${p.version_name||p.version_year} / ${p.topic}`).join('；')||'尚未关联考点'}}</p><section v-for="field in dimensionFields.filter(f=>card.content[f.key]?.length)" :key="field.key"><h4>{{field.name}}</h4><p class="preserve">{{card.content[field.key].join('\n')}}</p></section><section v-if="card.content.facts?.length"><h4>事实与适用前提</h4><article v-for="fact in card.content.facts" :key="fact.id"><p class="preserve">{{fact.text}}</p><small>前提：{{fact.applies_when||'未注明'}} · 来源：{{fact.source||card.source||'未注明'}}</small></article></section><section v-if="card.content.reference"><h4>真题参考 · {{card.content.reference.year}}</h4><p class="preserve">{{card.content.reference.stem}}</p><p v-for="o in card.content.reference.options" :key="o.label">{{o.label}}. {{o.text}}</p><p>参考答案：{{card.content.reference.answer||'未填写'}}</p><p class="preserve">{{card.content.reference.explanation}}</p></section><section v-if="card.content.custom_text"><h4>自定义内容</h4><p class="preserve">{{card.content.custom_text}}</p></section><section v-if="card.content.expression"><h4>表达要求</h4><p class="preserve">{{card.content.expression.instructions||'未填写'}}</p><h4>解析附言</h4><p class="preserve">{{card.content.expression.explanation_note||'未填写'}}</p></section><h4>来源与版本</h4><p class="preserve">{{card.source||'未填写'}}</p><template v-if="showNote&&card.note"><h4>维护备注</h4><p class="preserve">{{card.note}}</p></template></div></template>
<style scoped>.card-content{color:#425a73;font-size:13px;overflow-wrap:anywhere;line-height:1.8}.card-content h4{margin:16px 0 6px;font-size:13px;color:#263c54}.card-content p{margin:6px 0}.card-meta,.card-content small{color:#748396}.preserve{white-space:pre-wrap}.card-content article{padding:8px 12px;background:#f7faff;margin:8px 0;border-radius:5px}</style>
